package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class StringUtils_indexOfAnyBut_TriageGen0Test {

    private static final int INDEX_NOT_FOUND = -1;

    @Test
    public void testIndexOfAnyBut_NullStr() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut(null, "abc"));
    }

    @Test
    public void testIndexOfAnyBut_NullSearchChars() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("abc", null));
    }

    @Test
    public void testIndexOfAnyBut_EmptyStr() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("", "abc"));
    }

    @Test
    public void testIndexOfAnyBut_EmptySearchChars() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("abc", ""));
    }

    @Test
    public void testIndexOfAnyBut_NoMatchFound() {
        // All characters in str are present in searchChars
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("abc", "abcde"));
    }

    @Test
    public void testIndexOfAnyBut_MatchAtStart() {
        // First character is not in searchChars
        assertEquals(0, StringUtils.indexOfAnyBut("zabc", "abc"));
    }

    @Test
    public void testIndexOfAnyBut_MatchInMiddle() {
        // 'z' is in, 'a' is in, 'x' is NOT in
        assertEquals(2, StringUtils.indexOfAnyBut("zaxc", "zac"));
    }

    @Test
        public void testIndexOfAnyBut_MatchAtEnd() {
        assertEquals(2, StringUtils.indexOfAnyBut("abz", "ab"));
    }

    @Test
    public void testIndexOfAnyBut_SingleCharStr() {
        assertEquals(0, StringUtils.indexOfAnyBut("z", "abc"));
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("a", "abc"));
    }

    /**
     * Testing the High Surrogate branch logic.
     * The provided implementation has a specific logic for Character.isHighSurrogate(ch):
     * if (i + 1 < strLen && Character.isHighSurrogate(ch)) {
     *     char ch2 = str.charAt(i * 1); // Note: i * 1 is just i
     *     if (chFound && searchChars.indexOf(ch2) < 0) return i;
     * }
     */
    @Test
    public void testIndexOfAnyBut_HighSurrogateLogic() {
        // A high surrogate character (e.g., \uD83D)
        String highSurrogate = "\uD83D\uDE00"; // 😀

        // Case 1: High surrogate is in searchChars, but the logic checks ch2 (which is also ch in code)
        // Due to the bug/logic in the provided code: char ch2 = str.charAt(i * 1);
        // If chFound is true, and searchChars.indexOf(ch2) < 0 (impossible since chFound is true), 
        // it won't return i.

        // Test path where it goes to the 'else' block because isHighSurrogate is true but i+1 is not < strLen
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("\uD83D", "abc"));

        // Test path where it enters the surrogate block
        // If ch is found in searchChars, but ch2 (which is the same index) is NOT found? 
        // This is a contradiction in the provided code, but we test to cover the branch.
        // Since chFound = searchChars.indexOf(ch) >= 0, then searchChars.indexOf(ch2) cannot be < 0.
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut(highSurrogate, "\uD83D"));
    }

    @Test
    public void testIndexOfAnyBut_AllCharsInSearch() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("aaaaa", "a"));
    }

    @Test
    public void testIndexOfAnyBut_SpecialChars() {
        assertEquals(1, StringUtils.indexOfAnyBut("!@#", "@"));
    }
}
